-- Blue Ocean Ventures Knowledge Hub: Phase 3
-- Five funding programme research records and five institutional contact routes.
-- Run in Blue Ocean Supabase SQL Editor after phase 1/2.
-- Idempotent; does not alter existing records. No live calls or personal emails are claimed.

insert into public.bov_hub_records(category,title,summary,sectors,source_url,source_reference,verification,details)
select 'funding','UNDP — Country programme funding and partnerships','Development priorities include poverty reduction, governance, climate resilience and crisis response. Eligibility depends on the country programme, procurement or partnership notice.',array['Governance','Climate','Poverty','Resilience']::text[],'https://www.undp.org/','Official institutional source (verify current notice and contacts)','unverified','{"agency":"UNDP","eligibility":"Country- and instrument-specific; check official call","mechanisms":["Implementing partnership","Procurement","Country programme cooperation"],"contact_route":"UNDP country office","open_call_confirmed":false,"source_review_status":"Requires current official verification","research_batch":"phase3"}'::jsonb
where not exists (select 1 from public.bov_hub_records where category='funding' and title='UNDP — Country programme funding and partnerships');

insert into public.bov_hub_records(category,title,summary,sectors,source_url,source_reference,verification,details)
select 'funding','UNICEF — Civil society partnership opportunities','UNICEF works with civil society partners on education, child protection, health, nutrition and WASH. Country-specific calls and due diligence determine eligibility.',array['Education','Health','WASH','Child protection']::text[],'https://www.unpartnerportal.org/landing/opportunities/','Official institutional source (verify current notice and contacts)','unverified','{"agency":"UNICEF","eligibility":"CSO eligibility and organisational due diligence; consult individual notice","mechanisms":["Implementing partnership","UN Partner Portal"],"contact_route":"UNICEF country office or listed opportunity contact","open_call_confirmed":false,"source_review_status":"Requires current official verification","research_batch":"phase3"}'::jsonb
where not exists (select 1 from public.bov_hub_records where category='funding' and title='UNICEF — Civil society partnership opportunities');

