select 'funding','UNESCO — Participation Programme','UNESCO Participation Programme supports eligible Member State requests and qualifying NGOs in official partnership. Applicable cycle, ceiling and submission route must be confirmed from current UNESCO circular.',array['Education','Culture','Science']::text[],'https://www.unesco.org/en/participation-programme','Official institutional source (verify current notice and contacts)','unverified','{"agency":"UNESCO","eligibility":"Member States and eligible NGOs in official partnership, subject to programme rules","mechanisms":["Participation Programme"],"contact_route":"National Commission for UNESCO or official programme contact","open_call_confirmed":false,"source_review_status":"Requires current official verification","research_batch":"phase3"}'::jsonb
where not exists (select 1 from public.bov_hub_records where category='funding' and title='UNESCO — Participation Programme');

